import { Home, MoreHorizontal } from "lucide-react";
import { groupThemes, memberColors, formatBalance } from "../../data/groups";

function GroupCard({ group }) {
  const theme = groupThemes[group.theme] || groupThemes.green;

  const balanceColor =
    group.balance > 0
      ? "text-money"
      : group.balance < 0
      ? "text-rose"
      : "text-slate-500";

  return (
    <div className="overflow-hidden rounded-3xl bg-white border border-slate-200 shadow-sm">
      <div className={`h-2 ${theme.bar}`} />
      <div className="p-8">
        <div className="flex items-start justify-between">
          <div
            className={`w-14 h-14 rounded-2xl flex items-center justify-center ${theme.iconBg} ${theme.iconText}`}
          >
            <Home size={24} />
          </div>
          <button
            className="text-slate-400 hover:text-ink transition-colors"
            aria-label="Group options"
          >
            <MoreHorizontal size={22} />
          </button>
        </div>

        <h3 className="mt-8 text-2xl font-bold tracking-tight">{group.name}</h3>
        <p className="mt-1 text-slate-500">{group.meta}</p>

        <div className="mt-10 flex items-end justify-between">
          <div>
            <p className="font-mono text-xs tracking-widest uppercase text-slate-400">
              Your balance
            </p>
            <p className={`mt-1 font-mono text-3xl font-bold ${balanceColor}`}>
              {formatBalance(group.balance)}
            </p>
          </div>

          <div className="flex -space-x-2">
            {group.members.map((m, i) => (
              <span
                key={`${m}-${i}`}
                className={`w-10 h-10 rounded-full border-2 border-white text-xs font-semibold flex items-center justify-center ${
                  m.startsWith("+")
                    ? "bg-slate-100 text-slate-600"
                    : `${memberColors[i % memberColors.length]} text-ink`
                }`}
              >
                {m}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default GroupCard;
